from math import sqrt

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def min_operations(a, b):
    spf_a = prime_factors(a)
    spf_b = prime_factors(b)
    num_divisors_a = len(spf_a)
    num_divisors_b = len(spf_b)
    if num_divisors_a == num_divisors_b:
        return 0
    if num_divisors_a < num_divisors_b:
        smallest = min(n for p, n in zip(spf_a, spf_b) if n > 1)
        while smallest in spf_a:
            a //= smallest
            num_divisors_a -= spf_a.count(smallest)
            spf_a = prime_factors(a)
        num_divisors_a += spf_a.count(smallest)
        return 1 + bin_search_for_smallest(1, len(spf_a), spf_a)
    else:
        smallest = min(n for p, n in zip(spf_a, spf_b) if n > 1)
        while smallest in spf_b:
            b //= smallest
            num_divisors_b -= spf_b.count(smallest)
            spf_b = prime_factors(b)
        num_divisors_b += spf_b.count(smallest)
        return 1 + bin_search_for_smallest(1, len(spf_b), spf_b)

def bin_search_for_smallest(start, end, prime_factors):
    while start + 1 < end:
        mid = (start + end) // 2
        if len(prime_factors) <= mid:
            return mid
        elif len(prime_factors) > mid and prime_factors[len(prime_factors) - mid - 1] < mid + 1:
            start = mid + 1
        elif len(prime_factors) > mid and prime_factors[len(prime_factors) - mid - 1] >= mid + 1:
            end = mid
    return end

