import random

def split_and_permute(A, K, P):
    N = len(A)
    S = [list(A[i:i+K]) for i in range(0, N, K)]
    S = [s for s in S if s]  # Remove empty subsequences
    P = [P[i] for i in range(K) if i < 2 * K // 3]  # Select the top-thirds of P
    return [s[P[i]] for i in range(K) for s in S if i % 2 == P[i]]

def longest_increasing_subsequence(A):
    if len(A) == 1:
        return 1, A
    elif len(A) == 2:
        return 2, A
    else:
        return_recursive = 0
        for i in range(1, len(A)):
            if A[i] > A[i-1]:
                if longest_increasing_subsequence([A[i]] + A[:i-1] + A[i+1:])[0] > return_recursive:
                    return_recursive = longest_increasing_subsequence([A[i]] + A[:i-1] + A[i+1:])[0]
        return return_recursive + 1, A[:return_recursive]

def main():
    N, K = map(int, input().split())
    A = list(map(int, input().split()))
    B = split_and_permute(A, K, list(range(K)))
    L_A, L_B = sorted(longest_increasing_subsequence(B))[-1], N
    print(" ".join(map(str, B)))

