    return (n1 == 1 or n1 % 2 == 0) and (n2 == 1 or n2 % 2 == 0) and (n3 == 1 or n3 % 2 == 0)

def honeycomb(n1, n2, n3):
    count = 0
    if is_divisible(n1, n2, n3):
        count += n1 * n2
    if n1 == 1 or n1 % 2 == 0:
        count += n2 * (n3 + 1)
    if n2 == 1 or n2 % 2 == 0:
        count += n1 * (n3 + 1)
    if is_divisible(n3, n1, n2):
        count += n3 * (n1 + n2)
    return count

def info_sent(masses, areas, s):
    if not math.isqrt(s) * math.isqrt(s) == s:
        return 0
    return areas - honeycomb(masses[0], areas, s) - honeycomb(masses[1], areas, s)

