def count_triangles(n, m):
    total_decks = 0
    sides = n + 1
    for i in range(1, sides):
        total_decks += min(i * (i + 1) // 2, n)
        if i <= m:
            total_decks += (sides - i + 1) * (min((i - 1) * (i), n) + (sides - i))
        elif m < sides - i + 1:
            total_decks += (sides - 1 - i + 1) * (sides - 1 - i + 2)
        else:
            break
    return total_decks

