    super_prime_count = [1] + [sum(n % p for p in primes) for n in range(2, N+1) if not any(n % p for p in primes)]
    # Return the answer
    return int(S_per_k[1] + sum(super_prime_count[n-1] - prod(primes + [i+1] + list(range(i+1, i+10))) for i in range(K)))

