import random
from bisect import bisect_right

def build_quicksort_tree(A, N):
    if N <= 1:
        return [], A

    pivot = random.choice(range(1, N))
    left, A, right = [], [x for x in A[:pivot-1] if x != N] + [N], [x for x in A[pivot-1:] if x != N]

    left, B = build_quicksort_tree(left, len(left)-1)
    return left, A[0:N-1] + sorted(B + [N]) + A[N:]

def merge_sort(B, N):
    if N <= 1:
        return B

    mid = N // 2
    A, B = [], [x for x in B if x != N]

    A, C = merge_sort(A, mid)
    B, C = merge_sort(B, N-mid)

    B, C = merge_to_A(B, C, N)

    return A + B

def merge_to_A(A, B, N):
    M = [None for _ in range(N)]
    i = j = 0
    while i < len(A) and j < len(B):
        if A[i] < B[j]:
            M[i + j] = A[i]
            i += 1
        else:
            M[i + j] = B[j]
            j += 1

    while i < len(A):
        M[i + j] = A[i]
        i += 1

    while j < len(B):
        M[i + j] = B[j]
        j += 1

    return M, A+len(A)

def max_length_increasing_subsequence(A):
    if len(A) <= 1:
        return 0

    B = [A[0]]
    B_score = 0

    for i in range(1, len(A)):
        peak_index = bisect_right(B, A[i])
        B[peak_index-1:i+1] = map(lambda x: x + B[peak_index-1], B[peak_index-1:i+1])
        if peak_index <= 1:
            B_score = max(2, B_score)  # Avoid creating up to 2 subsequences of at most 1 element

    return max(B_score, 1)

if __name__ == "__main__":
    N, K = map(int, input().split())
    A = list(map(int, input().split()))

    A, B = build_quicksort_tree(A, N)
    B_sort = merge_sort(B, N)
    longest_suffix = max(length := max_length_increasing_subsequence(B[1:-1]))

    print(' '.join(map(str, B_sort[:1] + [i+1 for i, seq in enumerate(B_sort[1:-1]) if seq == length] + B_sort[-2:])))
