def find_bridges(n, adj, bridges):
    parent = list(range(n + 1))
    size = [0] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px = find(x)
        py = find(y)
        if px != py:
            if size[px] < size[py]:
                parent[px] = py
                size[py] += size[px]
            else:
                parent[py] = px
                size[px] += size[py]
            bridges[find(x)] = 0
            bridges[find(y)] = 0

    for i in range(1, n):
        discovery_time = set()
        for u, v, w in adj[i]:
            if find(u) != find(v):
                discovery_time.add(w)
                union(u, v)
    return discovery_time

