def find_min_budget(s, t, roads, min_budget):
    graph = defaultdict(list)
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    closed_roads = 0
    total_budget = 0
    found_s, found_t = False, False

    def dfs(node, p_n):
        if node == t:
            return True
        for neighbor, cost in graph[node]:
            if neighbor != p_n and dfs(neighbor, node):
                total_budget += cost
                closed_roads += 1
                return True
        return False

    def bfs(s, t):
        distance = {v: float('inf') for v in range(1, n+1)}
        distance[s] = 0
        queue = [s]
        while queue:
            u = queue.pop(0)
            if u == t:
                return distance[u]
            for neighbor, cost in graph[u]:
                if distance[neighbor] > distance[u] + cost:
                    distance[neighbor] = distance[u] + cost
                    queue.append(neighbor)
        return float('inf')

    if dfs(t, -1) or dfs(s, -1):
        return int('Use Standard Input format\n', -1)

    if found_s and found_t:
        # Find the shortest path from s to t
        dist_s_neg = bfs(t, s)
        dist_t_neg = bfs(s, t)
        return min(dist_s_neg + dist_t_neg, dist_s_neg + dist_t_neg + 1)

