    mod_pow = lambda x, pow: powmod(x, pow, MOD) if pow < 0 else powmod(x, pow)

    # Initialize prefix sums
    row_sums = [0 for _ in range(rows)]
    col_sums = [0 for _ in range(cols)]

    for q, x, v in operations:
        if q == 0:
            row_sums[x-1] = (row_sums[x-1] * v + v * cols) % MOD
        else:
            col_sums[x-1] = (col_sums[x-1] * v + v * rows) % MOD

    # Compute the final values
    final_values = [0] * (rows+cols)
    for k in range(min(rows, cols)):
        final_values[k] = (row_sums[k] * col_sums[-k-1]) % MOD
    for n in range(min(rows, cols), min(min(rows, cols)+10, rows+cols)): 
        final_values[n] = (final_values[n-rows] % MOD) * mod_pow(v, cols) % MOD
    for n in range(min(rows, cols), min(min(rows, cols)+10, rows+cols)):
        final_values[n] = (final_values[n-cols] % MOD) * mod_pow(v, rows) % MOD

    return sum(final_values) % MOD

def powmod(base, exp, mod):
    result = 1
    base = base % mod
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        exp = exp >> 1
        base = (base * base) % mod
    return result

