            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def minimum_operations(a, b):
    a_factors = prime_factors(a)
    b_factors = prime_factors(b)
    a_count = len(a_factors)
    b_count = len(b_factors)
    if a_factors == b_factors:
        return 0
    if a_factors < b_factors:
        a_factors, b_factors = b_factors, a_factors
    current_product = 1
    count_a = 0
    for prime in b_factors:
        if prime != a_factors[-1]:
            count_a += (a_factors[::-1][:count_a + 1] + [prime])[0]
            for i in range(1, count_a + 1):
