def largest_prime_factor(n):
    i = 2
    largest = 1
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            largest = i
    if n > 1:
        largest = n
    return largest

def count_distinct_prime_factors(n):
    prime_factors = {}
    while n % 2 == 0:
        if 2 not in prime_factors:
            prime_factors[2] = 1
        else:
            prime_factors[2] += 1
        n //= 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            if i not in prime_factors:
                prime_factors[i] = 1
            else:
                prime_factors[i] += 1
            n //= i
        i += 2
    if n > 2:
        prime_factors[n] = 1
    return len(prime_factors)

def special_sum(arr, K, S):
    max_sum = 0
    n = len(arr)
    for i in range(n):
        cur_sum = 0
        for j in range(i, n):
            cur_sum += arr[j]
            distinct_factors = count_distinct_prime_factors(cur_sum * K - S * i)
            max_sum = max(max_sum, cur_sum * (K - S[distinct_factors - 1]))
    return max_sum

