def solve(n, k, s):
    operations = []
    set_positions = set()
    for i in range(n):
        if s[i] in set_positions:
            operations.append('L')
            set_positions.remove(s[i])
        elif s[i] not in set_positions:
            operations.append('R')
            set_positions.add(s[i])
    for i in range(n):
        s = list(s)
        if s.count(s[i]) > k:
            operations.append('R')
        else:
            if s.count(s[i]) == k:
                if s[i] == 'a' and (s[i-1] == 'z' or (i+1) % n == k):
                    operations.append('L')
                else:
                    operations.append('D')
            else:
                count = s.count(s[i])
                sequence = list(s)
                j = i
                while count > 0:
                    k = (j + (n - i) // k) % (n - 1)
                    i = (j + k) % (n - 1)
                    s[j] = sequence[j]
                    count -= 1
                    j = i
    return ''.join(apply_operations(s, operations, k))

